//! A full encode through a user-provided VapourSynth script that modifies one detected
//! scene, ignored by default because it needs VapourSynth, BestSource, FFmpeg, and x264.
//!
//! Run with
//! `cargo test -p av1ation-engine --test script_scenes -- --ignored`.
//!
//! The three colour scenes are generated by FFmpeg into a per-test scratch directory; no
//! clip is committed or read from the machine.
//!
//! The point of these tests is timing. A `VapourSynthScript` input is evaluated when it is
//! opened, before Scene Detector has run and again before each later sequence. A script that
//! selects scenes or reads Noise Detector's result therefore only works if the runner
//! reopens the graph with the engine's current data, which is what `RealRunner` does. If the
//! graph is never rebuilt, the script keeps the empty table from start-up and the
//! modification is absent from the encoded output.

use std::{
    path::{Path, PathBuf},
    process::Command,
    sync::{Arc, Mutex},
    time::{Duration, Instant},
};

use andean_condor::models::{
    encoder::{Encoder, EncoderBase},
    scene::Scene,
    sequence::{
        DefaultSequenceConfig, DefaultSequenceData,
        noise_detector::{NoiseDetectorConfig, NoiseDetectorData},
    },
};
use av1ation_engine::{
    EncodeEventKind, EncodeRequest, EncodeRunner, RealRunner, capability::preflight,
    media::video::native_output,
};
use av1ation_test_support::{Clip, Scratch, ffmpeg};

const SEQUENCES: [&str; 3] = ["SceneDetector", "ParallelEncoder", "SceneConcatenator"];

/// A script that inverts the second of three scenes, choosing the range from the scene table
/// injected into `condor_scenes`. `json.loads` fails loudly when the runner does not inject
/// the table, so a missing injection cannot pass as "nothing to modify".
const SCRIPT: &str = r#"
import json
import vapoursynth as vs
core = vs.core

scenes = json.loads(condor_scenes)
sequence = condor_sequence.decode()
base = core.bs.VideoSource(source=condor_source)

if not scenes:
    # Scene Detector has not run yet. The runner reopens this script with the table, so a
    # script must build the unmodified graph rather than fail on an empty selection.
    base.set_output()
else:
    parts = []
    previous = 0
    for scene in scenes:
        start = scene["start"]
        end = scene["end"]
        if start > previous:
            parts.append(base[previous:start])
        # This scene is modified only when the graph was rebuilt for the encoder and the
        # engine's own scene-detection data is present, which proves both per-sequence
        # re-evaluation and that sequence data reaches the script.
        modify = (
            scene["index"] == 1
            and sequence == "ParallelEncoder"
            and scene["data"].get("scene_detection") is not None
        )
        if modify:
            parts.append(core.std.Invert(base[start:end], planes=[0]))
        else:
            parts.append(base[start:end])
        previous = end
    if previous < len(base):
        parts.append(base[previous:])

    clip = parts[0]
    for part in parts[1:]:
        clip = clip + part
    clip.set_output()
"#;

/// The same idea, but the modification is gated on Noise Detector's result rather than on
/// the scene table alone. A resumed run starts after detection, so the saved scenes carry
/// `noise_detection` before the first sequence opens.
const NOISE_SCRIPT: &str = r#"
import json
import vapoursynth as vs
core = vs.core

scenes = json.loads(condor_scenes)
base = core.bs.VideoSource(source=condor_source)

parts = []
previous = 0
for scene in scenes:
    start = scene["start"]
    end = scene["end"]
    if start > previous:
        parts.append(base[previous:start])
    modify = scene["index"] == 1 and scene["data"].get("noise_detection") is not None
    if modify:
        parts.append(core.std.Invert(base[start:end], planes=[0]))
    else:
        parts.append(base[start:end])
    previous = end
if previous < len(base):
    parts.append(base[previous:])

clip = parts[0]
for part in parts[1:]:
    clip = clip + part
clip.set_output()
"#;

/// The same selection again, but through the generated `condor_data` module instead of the
/// raw variables. The module is written into the scenes directory before every open, so a
/// script that imports it must see the table for the sequence it is being reopened for
/// rather than the empty table of the first open.
const MODULE_SCRIPT: &str = r#"
import sys
import vapoursynth as vs

sys.path.insert(0, condor_temp_dir.decode())
import condor_data as cd

core = vs.core
base = core.bs.VideoSource(source=cd.video_path)

if not cd.scenes:
    base.set_output()
else:
    parts = []
    previous = 0
    for scene in cd.scenes:
        if scene.start > previous:
            parts.append(base[previous : scene.start])
        modify = (
            scene.index == 1
            and cd.sequence == "ParallelEncoder"
            and scene.sequence_data.noise_detection is not None
        )
        if modify:
            parts.append(core.std.Invert(base[scene.start : scene.end], planes=[0]))
        else:
            parts.append(base[scene.start : scene.end])
        previous = scene.end
    if previous < len(base):
        parts.append(base[previous:])

    clip = parts[0]
    for part in parts[1:]:
        clip = clip + part
    clip.set_output()
"#;

fn vapoursynth_available() -> bool {
    preflight::detect()
        .iter()
        .any(|probe| probe.id == "vapoursynth" && probe.available)
}

/// The mean absolute luma difference between the same frame of two files, as a cheap way to
/// tell an inverted colour scene from an untouched one.
fn frame_difference(source: &Path, output: &Path, frame: u32) -> f64 {
    let read = |path: &Path| -> Vec<u8> {
        let result = Command::new(ffmpeg())
            .args(["-hide_banner", "-loglevel", "error", "-i"])
            .arg(path)
            .args([
                "-vf",
                &format!("select=eq(n\\,{frame})"),
                "-vsync",
                "0",
                "-frames:v",
                "1",
                "-f",
                "rawvideo",
                "-pix_fmt",
                "gray",
                "-",
            ])
            .output()
            .expect("ffmpeg decodes a frame");
        assert!(
            result.status.success(),
            "ffmpeg could not decode frame {frame} of {}: {}",
            path.display(),
            String::from_utf8_lossy(&result.stderr)
        );
        assert!(!result.stdout.is_empty(), "frame {frame} is missing");
        result.stdout
    };

    let original = read(source);
    let encoded = read(output);
    assert_eq!(original.len(), encoded.len(), "the frame size changed");
    let total: u64 = original
        .iter()
        .zip(&encoded)
        .map(|(a, b)| u64::from(a.abs_diff(*b)))
        .sum();
    total as f64 / original.len() as f64
}

fn run_script_encode(
    name: &str,
    script: &str,
    condor: Option<serde_json::Value>,
    sequences: &[&str],
    noise_detection: bool,
) -> (Scratch, Clip, PathBuf, Option<EncodeEventKind>) {
    let scratch = Scratch::new(&format!("av1ation-script-{name}"));
    let source = Clip::colour_scenes(scratch.path(), &["red", "blue", "green"], 320, 240, 24, 1);
    let output = scratch.join("output.mkv");
    let scenes_directory = scratch.join("scenes");
    std::fs::create_dir_all(&scenes_directory).expect("scenes dir");

    let mut config = DefaultSequenceConfig::default();
    config.parallel_encoder.scenes_directory = scenes_directory.clone();
    config.parallel_encoder.workers = Some(1);
    config.scene_concatenator.scenes_directory = scenes_directory;
    config.scene_concatenator.output = Some(output.clone());
    if noise_detection {
        // Empty filter lists measure the clip against itself: enough to write a real
        // `noise_detection` record without requiring the optional WNNM plugin.
        config.noise_detector = Some(NoiseDetectorConfig {
            input: None,
            reference_filters: Vec::new(),
            denoised_filters: Vec::new(),
        });
    }

    let mut encoder = Encoder::default_from_base(&EncoderBase::X264, false);
    encoder.set_quantizer(18.0);

    let input = serde_json::json!({
        "VapourSynthScript": {
            "source": { "Text": script },
            "variables": { "condor_source": source.path().display().to_string() },
            "index": 0,
            "filters": [],
            "stream_concurrently": true
        }
    });

    let saves = Arc::new(Mutex::new(Vec::new()));
    let saves_for_callback = Arc::clone(&saves);
    let request = EncodeRequest {
        run_id: format!("script-scenes-{name}"),
        project_id: "project".to_owned(),
        video_id: "video".to_owned(),
        input,
        video_path: source.path().display().to_string(),
        output: native_output(output.to_str().expect("utf-8 output path")),
        encoder: serde_json::to_value(&encoder).expect("encoder json"),
        sequence_config: serde_json::to_value(&config).expect("config json"),
        condor,
        sequences: sequences.iter().map(|id| (*id).to_owned()).collect(),
        checkpoint: Arc::new(move |value| {
            saves_for_callback
                .lock()
                .expect("checkpoint slot")
                .push(value);
            Ok(())
        }),
    };

    let handle = RealRunner.start(request).expect("runner starts");
    let deadline = Instant::now() + Duration::from_secs(240);
    let mut terminal = None;
    while Instant::now() < deadline {
        let Ok(event) = handle.events.recv_timeout(Duration::from_secs(1)) else {
            continue;
        };
        println!("{} {:?} {}", event.seq, event.kind, event.message);
        if event.kind.is_terminal() {
            terminal = Some(event.kind);
            break;
        }
    }

    // The detected scene table must be in the saved engine blob: this is the data the
    // script is supposed to receive, and it proves detection happened before encoding.
    let saved = saves.lock().expect("checkpoint slot");
    let last = saved.last().and_then(|value| value.get("scenes"));
    assert!(
        last.and_then(serde_json::Value::as_array)
            .is_some_and(|scenes| scenes.len() >= 3),
        "the runner did not checkpoint at least three detected scenes: {last:?}"
    );

    (scratch, source, output, terminal)
}

#[test]
#[ignore = "needs FFmpeg, VapourSynth and an encoder; run with --ignored"]
fn a_script_sees_noise_detection_results_in_a_resumed_encode() {
    if !vapoursynth_available() {
        println!("skipped: VapourSynth is not available on this machine");
        return;
    }

    let mut encoder = Encoder::default_from_base(&EncoderBase::X264, false);
    encoder.set_quantizer(18.0);

    let scene = |start: usize, end: usize, noise: Option<NoiseDetectorData>| Scene {
        start_frame: start,
        end_frame: end,
        sub_scenes: None,
        encoder: encoder.clone(),
        sequence_data: DefaultSequenceData {
            noise_detection: noise,
            ..Default::default()
        },
    };
    let scenes = vec![
        scene(0, 24, None),
        scene(
            24,
            48,
            Some(NoiseDetectorData {
                noise: 5.5,
                luminance: 0.4,
                created_on: std::time::UNIX_EPOCH,
            }),
        ),
        scene(48, 72, None),
    ];

    let (_scratch, source, output, terminal) = run_script_encode(
        "noise",
        NOISE_SCRIPT,
        Some(serde_json::json!({ "scenes": scenes })),
        &["ParallelEncoder", "SceneConcatenator"],
        false,
    );

    assert_eq!(
        terminal,
        Some(EncodeEventKind::Finished),
        "the resumed encode did not finish"
    );
    assert!(output.exists(), "the concatenated output is missing");

    let untouched = frame_difference(source.path(), &output, source.frame_at(0.5));
    let modified = frame_difference(source.path(), &output, source.frame_at(1.5));
    assert!(
        untouched < 8.0,
        "the unmodified scene changed too much ({untouched:.1})"
    );
    assert!(
        modified > 60.0,
        "Noise Detector's saved result did not reach the script ({modified:.1})"
    );
}

#[test]
#[ignore = "needs FFmpeg, VapourSynth and an encoder; run with --ignored"]
fn a_script_sees_noise_detection_in_the_same_run() {
    if !vapoursynth_available() {
        println!("skipped: VapourSynth is not available on this machine");
        return;
    }

    let (_scratch, source, output, terminal) = run_script_encode(
        "live-noise",
        NOISE_SCRIPT,
        None,
        &[
            "SceneDetector",
            "NoiseDetector",
            "ParallelEncoder",
            "SceneConcatenator",
        ],
        true,
    );

    assert_eq!(
        terminal,
        Some(EncodeEventKind::Finished),
        "the live-noise encode did not finish"
    );
    assert!(output.exists(), "the concatenated output is missing");

    let untouched = frame_difference(source.path(), &output, source.frame_at(0.5));
    let modified = frame_difference(source.path(), &output, source.frame_at(1.5));
    assert!(
        untouched < 8.0,
        "the unmodified scene changed too much ({untouched:.1})"
    );
    assert!(
        modified > 60.0,
        "Noise Detector's result did not reach the script before Parallel Encoder ({modified:.1})"
    );
}

/// The generated module has to describe the open it is imported by. VapourSynth evaluates
/// each open in one Python runtime, so a module imported during Scene Detector's open is
/// still in `sys.modules` when Parallel Encoder reopens the script; a module whose values
/// are baked in at import would keep the empty first table.
#[test]
#[ignore = "needs FFmpeg, VapourSynth and an encoder; run with --ignored"]
fn the_generated_module_describes_the_open_that_imports_it() {
    if !vapoursynth_available() {
        println!("skipped: VapourSynth is not available on this machine");
        return;
    }

    let (_scratch, source, output, terminal) = run_script_encode(
        "module",
        MODULE_SCRIPT,
        None,
        &[
            "SceneDetector",
            "NoiseDetector",
            "ParallelEncoder",
            "SceneConcatenator",
        ],
        true,
    );

    assert_eq!(
        terminal,
        Some(EncodeEventKind::Finished),
        "the module-script encode did not finish"
    );
    let untouched = frame_difference(source.path(), &output, source.frame_at(0.5));
    let modified = frame_difference(source.path(), &output, source.frame_at(1.5));
    assert!(
        untouched < 8.0,
        "the unmodified scene changed too much ({untouched:.1})"
    );
    assert!(
        modified > 60.0,
        "the module kept the first open's empty table ({modified:.1})"
    );
}

#[test]
#[ignore = "needs FFmpeg, VapourSynth and an encoder; run with --ignored"]
fn a_script_modifies_one_detected_scene_in_a_full_encode() {
    if !vapoursynth_available() {
        println!("skipped: VapourSynth is not available on this machine");
        return;
    }

    let (_scratch, source, output, terminal) =
        run_script_encode("injected", SCRIPT, None, &SEQUENCES, false);

    assert_eq!(
        terminal,
        Some(EncodeEventKind::Finished),
        "the script encode did not finish"
    );
    assert!(output.exists(), "the concatenated output is missing");

    // Frame 36 is inside the second scene; frame 12 is inside the untouched first scene.
    let untouched = frame_difference(source.path(), &output, source.frame_at(0.5));
    let modified = frame_difference(source.path(), &output, source.frame_at(1.5));

    assert!(
        untouched < 8.0,
        "the unmodified scene changed too much ({untouched:.1}); the script applied its \
         inversion outside the selected scene"
    );
    assert!(
        modified > 60.0,
        "the modified scene was not inverted in the output ({modified:.1}); the script's \
         scene-selected modification did not reach the encoder"
    );
}
